import sys
from collections import defaultdict

def group(strs):
    groups = defaultdict(list)
    for s in strs:
        key = ''.join(sorted(s))
        groups[key].append(s)
    return sorted(groups.values(), key=lambda g: sorted(g)[0])

if __name__ == '__main__':
    data = sys.stdin.read().split()
    n = int(data[0]) if data else 0
    if n == 0:
        print(); sys.exit(0)
    strs = data[1:1 + n]
    for g in group(strs):
        print(' '.join(sorted(g)))

import sys
from collections import defaultdict

def group(strs):
    groups = defaultdict(list)
    for s in strs:
        cnt = [0] * 26
        for ch in s:
            cnt[ord(ch) - ord('a')] += 1
        groups[tuple(cnt)].append(s)
    return sorted(groups.values(), key=lambda g: sorted(g)[0])

